import json
from confluent_kafka import Producer, Consumer, KafkaError

# ---- Producer (reliable, keyed JSON) ----
producer = Producer({
    "bootstrap.servers": "localhost:9092",
    "acks": "all",              # wait for all in-sync replicas
    "enable.idempotence": True, # dedupe retries, preserve order
    "linger.ms": 5,             # small batching for throughput
    "compression.type": "lz4",
})

def delivery_report(err, msg):
    if err is not None:
        print(f"Delivery failed for key {msg.key()}: {err}")
    else:
        print(f"Delivered to {msg.topic()}[{msg.partition()}]@{msg.offset()}")

events = [("user-1", {"action": "click"}), ("user-2", {"action": "view"})]
for key, value in events:
    producer.produce(
        topic="events",
        key=key.encode("utf-8"),
        value=json.dumps(value).encode("utf-8"),
        callback=delivery_report,
    )
producer.flush()  # block until all messages are delivered

# ---- Consumer (manual commit, at-least-once) ----
consumer = Consumer({
    "bootstrap.servers": "localhost:9092",
    "group.id": "events-processor",
    "enable.auto.commit": False,   # commit manually after processing
    "auto.offset.reset": "earliest",
})
consumer.subscribe(["events"])

try:
    while True:
        msg = consumer.poll(timeout=1.0)
        if msg is None:
            continue
        if msg.error():
            if msg.error().code() == KafkaError._PARTITION_EOF:
                continue
            raise Exception(msg.error())
        record = json.loads(msg.value().decode("utf-8"))
        process(record)                 # do the work FIRST
        consumer.commit(message=msg, asynchronous=False)  # then commit
finally:
    consumer.close()

