def compute_consumer_lag(log_end_offsets, committed_offsets, threshold=None):
    """log_end_offsets: {partition: high_watermark}
    committed_offsets: {partition: last_committed_offset or None}
    Returns dict with per-partition lag, total lag, and flagged partitions."""
    per_partition = {}
    flagged = []
    total = 0

    for partition, leo in log_end_offsets.items():
        committed = committed_offsets.get(partition)
        if committed is None:
            # no committed offset yet: full backlog is unread
            lag = leo
        else:
            lag = max(0, leo - committed)  # clamp against stale metadata
        per_partition[partition] = lag
        total += lag
        if threshold is not None and lag > threshold:
            flagged.append((partition, lag))

    return {
        "per_partition_lag": per_partition,
        "total_lag": total,
        "flagged_partitions": flagged,
    }

