def lag_from_rows(rows, threshold=None):
    total, flagged = 0, []
    for p, leo, committed in rows:
        lag = leo if committed is None else max(0, leo - committed)
        total += lag
        if threshold and lag > threshold:
            flagged.append((p, lag))
    return total, flagged

