class IdempotentSink:
    def __init__(self):
        self.store = {}            # id -> {"value":..., "version":...}
        self.committed_offset = {} # partition -> last applied offset

    def _record_id(self, rec):
        # prefer a natural business key; else use Kafka coordinates
        if rec.get("business_key") is not None:
            return ("biz", rec["business_key"])
        return ("kafka", rec["topic"], rec["partition"], rec["offset"])

    def apply(self, rec):
        rid = self._record_id(rec)
        incoming_version = rec.get("version", 0)
        existing = self.store.get(rid)

        # idempotent + version-aware upsert
        if existing is None or incoming_version > existing["version"]:
            self.store[rid] = {"value": rec["value"], "version": incoming_version}
            applied = True
        else:
            applied = False  # duplicate or stale replay: no-op

        # advance offset only forward (resumption bookmark)
        p, off = rec["partition"], rec["offset"]
        self.committed_offset[p] = max(self.committed_offset.get(p, -1), off)
        return applied


def process_stream(records):
    sink = IdempotentSink()
    for rec in records:  # may include duplicates / replays
        sink.apply(rec)
    return sink.store, sink.committed_offset

from collections import defaultdict

def session_windows(events, gap_seconds=30 * 60):
    """events: iterable of (user_id, event_time_epoch_seconds).
    Returns list of sessions: (user_id, session_start, session_end, count)."""
    by_user = defaultdict(list)
    for user_id, ts in events:
        by_user[user_id].append(ts)

    sessions = []
    for user_id, times in by_user.items():
        times.sort()  # gap logic requires chronological order
        start = prev = times[0]
        count = 1
        for ts in times[1:]:
            if ts - prev > gap_seconds:
                # gap exceeded: close current session, open a new one
                sessions.append((user_id, start, prev, count))
                start = ts
                count = 1
            else:
                count += 1
            prev = ts
        sessions.append((user_id, start, prev, count))  # flush last session

    return sorted(sessions)

